stageCss:
#stage .eg-scene{ position:relative; width:100%; height:100%; display:flex; flex-direction:column; gap:14px; }

/* ============================== TOP STRIP ============================== */
#stage .eg-top{
  height:78px; flex-shrink:0; display:flex; align-items:center; gap:14px;
  padding:0 22px; border-radius:20px; white-space:nowrap;
  background:rgba(20,27,43,.78); border:1.5px solid var(--border);
}
#stage .eg-mark{
  width:46px; height:46px; border-radius:13px; flex-shrink:0;
  display:flex; align-items:center; justify-content:center;
  background:rgba(58,160,255,.14); border:1.5px solid rgba(58,160,255,.42); color:var(--accent-1);
}
#stage .eg-mark svg{ width:25px; height:25px; }
#stage .eg-app{
  color:var(--text-primary); font-family:var(--font-mono); font-size:21px; font-weight:600;
  overflow:hidden; text-overflow:ellipsis; min-width:0;
}
#stage .eg-lat{ margin-left:auto; flex-shrink:0; display:flex; align-items:baseline; gap:8px; }
#stage .eg-lat b{
  color:#fff; font-family:var(--font-mono); font-size:28px; font-weight:700;
  font-variant-numeric:tabular-nums; transition:color .3s ease;
}
#stage .eg-lat.bad b{ color:var(--danger); }
#stage .eg-lat.ok b{ color:var(--success); }
#stage .eg-lat i{ color:var(--text-dim); font-size:18px; font-weight:600; font-style:normal; }
#stage .eg-health{
  flex-shrink:0; display:flex; align-items:center; gap:8px; padding:7px 14px; border-radius:100px;
  border:1.5px solid rgba(63,185,80,.45); background:rgba(63,185,80,.1);
  transition:border-color .3s ease, background .3s ease;
}
#stage .eg-health i{
  width:10px; height:10px; border-radius:50%; background:var(--success);
  box-shadow:0 0 12px var(--success); animation:msd-breathe 2s ease-in-out infinite;
}
#stage .eg-health b{ color:var(--success); font-family:var(--font-mono); font-size:18px; font-weight:700; }
#stage .eg-health.warn{ border-color:rgba(240,166,74,.55); background:rgba(240,166,74,.12); }
#stage .eg-health.warn i{ background:var(--warn); box-shadow:0 0 12px var(--warn); animation-duration:.6s; }
#stage .eg-health.warn b{ color:var(--warn); }
#stage .eg-health.bad{ border-color:rgba(244,74,106,.55); background:rgba(244,74,106,.12); }
#stage .eg-health.bad i{ background:var(--danger); box-shadow:0 0 12px var(--danger); animation-duration:.45s; }
#stage .eg-health.bad b{ color:var(--danger); }

/* ============================= SCENE STACK ============================= */
#stage .eg-body{ position:relative; flex:1; min-height:0; }
#stage .eg-sc{
  position:absolute; inset:0; opacity:0; transform:scale(.986); pointer-events:none;
  transition:opacity .3s ease, transform .3s cubic-bezier(.22,1,.36,1);
}
#stage .eg-sc.on{ opacity:1; transform:none; }
#stage .eg-sc.whip{ animation:eg-whip .44s cubic-bezier(.19,1,.22,1); }

/* ==================== SCENE 1 · CALLING EVERYONE YOURSELF ============== */
#stage .eg-coupled{ display:flex; flex-direction:column; gap:14px; height:100%; }

#stage .eg-order{
  height:104px; flex-shrink:0; display:flex; align-items:center; gap:16px;
  padding:0 22px; border-radius:22px;
  background:linear-gradient(180deg, var(--bg-panel), var(--bg-panel-2));
  border:1.5px solid var(--border);
}
#stage .eg-order-ic{
  width:54px; height:54px; border-radius:15px; flex-shrink:0; font-size:27px;
  display:flex; align-items:center; justify-content:center;
  background:linear-gradient(160deg,#26344e,#1a2338); border:1.5px solid var(--border);
}
#stage .eg-order-t{ display:flex; flex-direction:column; gap:5px; min-width:0; }
#stage .eg-order-t b{ color:#fff; font-size:26px; font-weight:800; letter-spacing:-.3px; white-space:nowrap; }
#stage .eg-order-t i{ color:var(--text-dim); font-family:var(--font-mono); font-size:18px; font-weight:600; font-style:normal; white-space:nowrap; }
#stage .eg-order-b{
  margin-left:auto; flex-shrink:0; padding:8px 17px; border-radius:100px; white-space:nowrap;
  border:1.5px solid rgba(63,185,80,.5); background:rgba(63,185,80,.12); color:var(--success);
  font-family:var(--font-mono); font-size:18px; font-weight:700; letter-spacing:1.4px;
}

#stage .eg-svc{
  height:142px; flex-shrink:0; display:flex; flex-direction:column; gap:12px; justify-content:center;
  padding:16px 22px; border-radius:24px;
  background:linear-gradient(180deg, var(--bg-panel), var(--bg-panel-2));
  border:1.5px solid var(--border);
  transition:border-color .3s ease, box-shadow .3s ease;
}
#stage .eg-svc.busy{ border-color:rgba(240,166,74,.6); box-shadow:0 0 0 1px rgba(240,166,74,.24), 0 0 46px rgba(240,166,74,.14); }
#stage .eg-svc.bad{
  border-color:rgba(244,74,106,.65); box-shadow:0 0 0 1px rgba(244,74,106,.26), 0 0 50px rgba(244,74,106,.18);
  animation:eg-alert 1s ease-in-out infinite;
}
#stage .eg-svc-h{ display:flex; align-items:center; gap:14px; }
#stage .eg-svc-ic{
  width:50px; height:50px; border-radius:14px; flex-shrink:0;
  display:flex; align-items:center; justify-content:center;
  background:rgba(58,160,255,.12); color:var(--accent-1);
}
#stage .eg-svc-ic svg{ width:28px; height:28px; }
#stage .eg-svc-n{ color:#fff; font-size:28px; font-weight:800; letter-spacing:-.4px; }
#stage .eg-svc-b{
  margin-left:auto; padding:8px 17px; border-radius:100px; white-space:nowrap;
  border:1.5px solid rgba(240,166,74,.5); background:rgba(240,166,74,.12); color:var(--warn);
  font-family:var(--font-mono); font-size:18px; font-weight:700; letter-spacing:1.2px;
  transition:border-color .3s ease, background .3s ease, color .3s ease;
}
#stage .eg-svc-b.bad{ border-color:rgba(244,74,106,.6); background:rgba(244,74,106,.16); color:var(--danger); }
#stage .eg-svc-b.ok{ border-color:rgba(63,185,80,.5); background:rgba(63,185,80,.14); color:var(--success); }
#stage .eg-svc-s{ color:var(--text-dim); font-family:var(--font-mono); font-size:19px; font-weight:600; white-space:nowrap; }

#stage .eg-arrows, #stage .eg-fan{
  position:relative; flex-shrink:0; height:64px;
  display:flex; align-items:center; justify-content:flex-start; gap:52px; padding-left:70px;
}
#stage .eg-arrows i, #stage .eg-fan i{
  display:block; width:4px; height:30px; border-radius:2px;
  background:linear-gradient(180deg, rgba(58,160,255,.15), var(--accent-1));
  box-shadow:0 0 12px rgba(58,160,255,.5);
  animation:eg-drop 1.1s linear infinite;
}
#stage .eg-arrows i:nth-child(2), #stage .eg-fan i:nth-child(2){ animation-delay:.22s; }
#stage .eg-arrows i:nth-child(3), #stage .eg-fan i:nth-child(3){ animation-delay:.44s; }
#stage .eg-arrows i:nth-child(4), #stage .eg-fan i:nth-child(4){ animation-delay:.66s; }
#stage .eg-fan i{ background:linear-gradient(180deg, rgba(34,211,238,.15), var(--accent-cyan)); box-shadow:0 0 12px rgba(34,211,238,.5); }
#stage .eg-arrows-t, #stage .eg-fan-t{
  position:absolute; right:20px; top:50%; transform:translateY(-50%);
  color:var(--text-dim); font-family:var(--font-mono); font-size:19px; font-weight:600; white-space:nowrap;
}

#stage .eg-downs, #stage .eg-subs{ flex:1; min-height:0; display:flex; align-items:center; gap:12px; }
#stage .eg-down, #stage .eg-sub{
  flex:1; min-width:0; height:186px; display:flex; flex-direction:column; gap:9px; justify-content:center;
  padding:14px 14px; border-radius:20px;
  background:linear-gradient(180deg, var(--bg-panel), var(--bg-panel-2));
  border:1.5px solid var(--border);
  transition:opacity .3s ease, filter .3s ease, border-color .3s ease, box-shadow .3s ease;
}
#stage .eg-down.ghost, #stage .eg-sub.ghost{ opacity:.3; filter:saturate(.2); border-style:dashed; }
#stage .eg-down.ok, #stage .eg-sub.ok{
  border-color:rgba(63,185,80,.55); box-shadow:0 0 0 1px rgba(63,185,80,.2), 0 0 34px rgba(63,185,80,.12);
}
#stage .eg-down.bad, #stage .eg-sub.bad{
  border-color:rgba(244,74,106,.65); box-shadow:0 0 0 1px rgba(244,74,106,.24), 0 0 40px rgba(244,74,106,.16);
  animation:eg-alert 1s ease-in-out infinite;
}
#stage .eg-down.wait, #stage .eg-sub.wait{ border-color:rgba(240,166,74,.55); }
#stage .eg-down-h, #stage .eg-sub-h{ display:flex; align-items:center; gap:10px; }
#stage .eg-down-ic{ font-size:24px; flex-shrink:0; }
#stage .eg-down-h b, #stage .eg-sub-h b{
  color:#fff; font-family:var(--font-mono); font-size:19px; font-weight:700;
  white-space:nowrap; overflow:hidden; text-overflow:ellipsis;
}
#stage .eg-down-s, #stage .eg-sub-s, #stage .eg-down-l{
  font-family:var(--font-mono); font-size:17px; font-weight:600;
  white-space:nowrap; overflow:hidden; text-overflow:ellipsis;
}
#stage .eg-down-s, #stage .eg-sub-s{ color:var(--text-primary); }
#stage .eg-down-l{ color:var(--text-dim); }
#stage .eg-down.ok .eg-down-s, #stage .eg-sub.ok .eg-sub-s{ color:var(--success); }
#stage .eg-down.bad .eg-down-s, #stage .eg-sub.bad .eg-sub-s{ color:var(--danger); }
#stage .eg-down.wait .eg-down-s{ color:var(--warn); }
/* The filter is the line that decides whether this subscriber is even woken up,
   so it gets its own chip rather than living in the status line. */
#stage .eg-filter{
  padding:7px 10px; border-radius:9px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;
  background:rgba(58,160,255,.12); border:1px solid rgba(58,160,255,.35); color:var(--accent-1);
  font-family:var(--font-mono); font-size:15px; font-weight:600;
  transition:background .3s ease, border-color .3s ease, color .3s ease;
}
#stage .eg-filter.hot{ background:rgba(34,211,238,.18); border-color:rgba(34,211,238,.6); color:var(--accent-cyan); }
#stage .eg-filter.off{ background:rgba(139,149,167,.1); border-color:rgba(139,149,167,.3); color:var(--text-dim); }

#stage .eg-deploy{
  height:162px; flex-shrink:0; display:flex; flex-direction:column; gap:10px; justify-content:center;
  padding:14px 20px; border-radius:22px;
  background:rgba(20,27,43,.5); border:1.5px dashed var(--border);
  opacity:.32; filter:saturate(.25);
  transition:opacity .3s ease, filter .3s ease, border-color .3s ease, background .3s ease, box-shadow .3s ease;
}
#stage .eg-deploy.on{
  opacity:1; filter:none; border-style:solid; border-color:rgba(244,74,106,.6);
  background:rgba(244,74,106,.07);
  box-shadow:0 0 0 1px rgba(244,74,106,.2), 0 0 50px rgba(244,74,106,.14);
}
#stage .eg-deploy-h{ display:flex; align-items:center; gap:14px; }
#stage .eg-deploy-n{ color:#fff; font-size:23px; font-weight:800; letter-spacing:-.3px; white-space:nowrap; }
#stage .eg-deploy-b{
  margin-left:auto; padding:6px 14px; border-radius:100px; white-space:nowrap;
  border:1.5px solid rgba(244,74,106,.55); background:rgba(244,74,106,.14); color:var(--danger);
  font-family:var(--font-mono); font-size:16px; font-weight:800; letter-spacing:1.4px;
}
#stage .eg-code{ display:flex; flex-direction:column; gap:2px; }
#stage .eg-code-l{
  color:var(--text-dim); font-family:var(--font-mono); font-size:16px; font-weight:600;
  white-space:nowrap; overflow:hidden; text-overflow:ellipsis;
}
#stage .eg-code-l.add{ color:var(--danger); opacity:0; transition:opacity .3s ease; }
#stage .eg-code-l.add.show{ opacity:1; }

/* ================= SCENE 2 · THE TOPIC AND ITS SUBSCRIPTIONS =========== */
#stage .eg-grid{ display:flex; flex-direction:column; gap:14px; height:100%; }

#stage .eg-pub{
  height:104px; flex-shrink:0; display:flex; align-items:center; gap:16px;
  padding:0 22px; border-radius:22px;
  background:rgba(20,27,43,.6); border:1.5px solid var(--border);
}
#stage .eg-pub-ic{
  width:50px; height:50px; border-radius:14px; flex-shrink:0;
  display:flex; align-items:center; justify-content:center;
  background:rgba(34,211,238,.14); color:var(--accent-cyan);
}
#stage .eg-pub-ic svg{ width:28px; height:28px; }
#stage .eg-pub-t{ color:#fff; font-size:26px; font-weight:800; letter-spacing:-.3px; white-space:nowrap; }
#stage .eg-pub-b{
  margin-left:auto; flex-shrink:0; padding:9px 18px; border-radius:100px; white-space:nowrap;
  border:1.5px solid rgba(63,185,80,.5); background:rgba(63,185,80,.12); color:var(--success);
  font-family:var(--font-mono); font-size:19px; font-weight:700;
}

#stage .eg-topic{
  height:150px; flex-shrink:0; display:flex; flex-direction:column; gap:14px; justify-content:center;
  padding:16px 20px; border-radius:26px;
  background:radial-gradient(circle at 50% 0%, rgba(34,211,238,.12), transparent 62%), rgba(20,27,43,.6);
  border:2px solid rgba(34,211,238,.45);
  box-shadow:0 0 0 1px rgba(34,211,238,.16), 0 0 60px rgba(34,211,238,.12);
}
#stage .eg-topic-h{ display:flex; align-items:center; gap:14px; }
#stage .eg-topic-ic{
  width:48px; height:48px; border-radius:14px; flex-shrink:0; font-size:25px;
  display:flex; align-items:center; justify-content:center;
  background:rgba(34,211,238,.14); border:1.5px solid rgba(34,211,238,.4);
}
#stage .eg-topic-n{ color:#fff; font-size:25px; font-weight:800; letter-spacing:-.4px; white-space:nowrap; }
#stage .eg-topic-d{
  margin-left:auto; padding:7px 15px; border-radius:100px; white-space:nowrap;
  border:1.5px solid rgba(34,211,238,.5); background:rgba(34,211,238,.12); color:var(--accent-cyan);
  font-family:var(--font-mono); font-size:17px; font-weight:700;
}
#stage .eg-types{ display:flex; align-items:center; gap:10px; }
#stage .eg-type{
  padding:8px 13px; border-radius:10px; white-space:nowrap;
  background:rgba(14,20,32,.75); border:1.5px solid var(--border); color:var(--text-dim);
  font-family:var(--font-mono); font-size:17px; font-weight:600;
  transition:background .3s ease, border-color .3s ease, color .3s ease;
}
#stage .eg-type.on{ background:rgba(34,211,238,.18); border-color:rgba(34,211,238,.6); color:var(--accent-cyan); }
#stage .eg-subj{
  margin-left:auto; color:var(--text-dim); font-family:var(--font-mono);
  font-size:17px; font-weight:600; white-space:nowrap;
  transition:color .3s ease;
}
#stage .eg-subj.hot{ color:var(--accent-1); }

#stage .eg-dl{
  height:96px; flex-shrink:0; display:flex; align-items:center; gap:14px;
  padding:0 20px; border-radius:20px;
  background:rgba(20,27,43,.5); border:1.5px dashed var(--border);
  opacity:.34; filter:saturate(.25);
  transition:opacity .3s ease, filter .3s ease, border-color .3s ease, background .3s ease;
}
#stage .eg-dl.on{
  opacity:1; filter:none; border-style:solid; border-color:rgba(244,74,106,.55);
  background:rgba(244,74,106,.07);
}
#stage .eg-dl-ic{
  width:46px; height:46px; border-radius:13px; flex-shrink:0; font-size:24px;
  display:flex; align-items:center; justify-content:center;
  background:rgba(244,74,106,.12); border:1.5px solid rgba(244,74,106,.3);
}
#stage .eg-dl-n{ color:#fff; font-family:var(--font-mono); font-size:21px; font-weight:700; white-space:nowrap; }
#stage .eg-dl-s{
  margin-left:auto; color:var(--text-dim); font-family:var(--font-mono);
  font-size:18px; font-weight:600; white-space:nowrap;
}

#stage .eg-strip{
  height:72px; flex-shrink:0; display:flex; align-items:center; gap:16px;
  padding:0 22px; border-radius:20px;
  background:rgba(20,27,43,.7); border:1.5px solid var(--border);
  transition:border-color .3s ease, background .3s ease;
}
#stage .eg-strip b{
  padding:6px 15px; border-radius:8px; flex-shrink:0;
  background:rgba(58,160,255,.16); color:var(--accent-1);
  font-family:var(--font-mono); font-size:18px; font-weight:800; letter-spacing:2px;
}
#stage .eg-strip span{ color:var(--text-primary); font-size:22px; font-weight:600; line-height:1.3; }
#stage .eg-strip.bad{ border-color:rgba(244,74,106,.5); background:rgba(244,74,106,.1); }
#stage .eg-strip.bad b{ background:rgba(244,74,106,.2); color:var(--danger); }
#stage .eg-strip.good{ border-color:rgba(63,185,80,.45); background:rgba(63,185,80,.09); }
#stage .eg-strip.good b{ background:rgba(63,185,80,.2); color:var(--success); }

/* ===================== SCENE 3 · WHICH OF THE THREE ==================== */
#stage .eg-split{ display:flex; gap:14px; height:100%; }
#stage .eg-col{
  flex:1; min-width:0; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:14px;
  padding:22px 14px; border-radius:26px; text-align:center;
}
#stage .eg-col.bus{ background:rgba(20,27,43,.6); border:2px solid rgba(58,160,255,.42); }
#stage .eg-col.grid{
  background:radial-gradient(circle at 50% 0%, rgba(34,211,238,.16), transparent 62%), rgba(20,27,43,.6);
  border:2px solid rgba(34,211,238,.6);
  box-shadow:0 0 0 1px rgba(34,211,238,.2), 0 0 60px rgba(34,211,238,.14);
}
#stage .eg-col.hubs{ background:rgba(20,27,43,.6); border:2px solid rgba(58,160,255,.42); }
#stage .eg-col-h{ font-family:var(--font-mono); font-size:17px; font-weight:800; letter-spacing:1.2px; white-space:nowrap; }
#stage .eg-col.bus .eg-col-h, #stage .eg-col.hubs .eg-col-h{ color:var(--accent-1); }
#stage .eg-col.grid .eg-col-h{ color:var(--accent-cyan); }
#stage .eg-col-ic{ font-size:52px; line-height:1; }
#stage .eg-col.grid .eg-col-ic{ animation:msd-breathe 2.4s ease-in-out infinite; }
#stage .eg-col-list{ width:100%; display:flex; flex-direction:column; gap:9px; }
#stage .eg-row{
  padding:12px 8px; border-radius:12px;
  background:rgba(14,20,32,.7); border:1.5px solid var(--border); color:var(--text-dim);
  font-size:19px; font-weight:600; line-height:1.25;
}
#stage .eg-row b{ color:var(--text-primary); font-weight:800; }
#stage .eg-col.grid .eg-row b{ color:#fff; }
#stage .eg-col-x{
  width:100%; padding:12px 8px; border-radius:13px; white-space:nowrap;
  background:rgba(58,160,255,.12); border:1.5px solid rgba(58,160,255,.45); color:var(--accent-1);
  font-family:var(--font-mono); font-size:17px; font-weight:700;
}
#stage .eg-col-x.hot{ background:rgba(34,211,238,.16); border-color:rgba(34,211,238,.6); color:var(--accent-cyan); }

/* ========================== SCENE 4 · THE PAYOFF ======================= */
#stage .eg-final{
  height:100%; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:18px;
  text-align:center;
}
#stage .eg-badge{
  width:132px; height:132px; border-radius:36px; font-size:64px;
  display:flex; align-items:center; justify-content:center;
  background:linear-gradient(160deg, rgba(34,211,238,.28), rgba(58,160,255,.14));
  border:2px solid rgba(34,211,238,.6);
  box-shadow:0 0 0 1px rgba(34,211,238,.3), 0 0 80px rgba(34,211,238,.32);
  animation:msd-breathe 2.4s ease-in-out infinite;
}
#stage .eg-badge-l{ color:var(--accent-cyan); font-family:var(--font-mono); font-size:22px; font-weight:800; letter-spacing:5px; }
#stage .eg-fin-h{ color:#fff; font-size:58px; font-weight:900; line-height:1.14; letter-spacing:-1.6px; }
#stage .eg-fin-h em{ font-style:normal; color:var(--accent-cyan); }
#stage .eg-fin-row{ display:flex; flex-wrap:wrap; justify-content:center; gap:12px; }
#stage .eg-fin-p{
  padding:12px 20px; border-radius:100px; white-space:nowrap;
  background:rgba(20,27,43,.8); border:1.5px solid rgba(34,211,238,.42); color:var(--text-primary);
  font-size:22px; font-weight:700;
}
#stage .eg-save{
  margin-top:8px; padding:18px 26px; border-radius:20px; max-width:840px;
  background:linear-gradient(90deg, rgba(34,211,238,.2), rgba(58,160,255,.1));
  border:1.5px solid rgba(34,211,238,.55); color:#fff;
  font-size:26px; font-weight:700; line-height:1.35;
}
#stage .eg-save.ping{ animation:msd-punch .4s cubic-bezier(.22,1,.36,1); }

/* ============================== KEYFRAMES ============================== */
@keyframes eg-drop{
  0%{ transform:translateY(-16px); opacity:0; }
  25%{ opacity:1; }
  100%{ transform:translateY(20px); opacity:0; }
}
@keyframes eg-alert{
  0%,100%{ box-shadow:0 0 0 1px rgba(244,74,106,.3), 0 0 40px rgba(244,74,106,.16); }
  50%{ box-shadow:0 0 0 1px rgba(244,74,106,.55), 0 0 80px rgba(244,74,106,.3); }
}
@keyframes eg-whip{
  0%{ transform:translateX(220px) scale(1.04); filter:blur(16px); opacity:0; }
  55%{ filter:blur(3px); opacity:1; }
  100%{ transform:none; filter:blur(0); opacity:1; }
